INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2019f-am-01','exam-sg','サイバー攻撃・BEC','standard','single_choice','【2019年度 令和元年秋期 午前 問1】BEC（Business E-mail Compromise）に該当するものはどれか。','[{"id":"a","text":"巧妙なだましの手口を駆使し，取引先になりすまして偽の電子メールを送り，金銭をだまし取る。"},{"id":"b","text":"送信元を攻撃対象の組織のメールアドレスに詐称し，大量の実在しないアドレスにメールを送り，組織のアドレスをブラックリストに登録させる。"},{"id":"c","text":"第三者からのメールを中継できるよう設定されたメールサーバをスパムメールの中継に悪用する。"},{"id":"d","text":"送信元を攻撃対象組織のアドレスに詐称した誹謗中傷メールで組織の信用を損なわせる。"}]','"a"','BEC（ビジネスメール詐欺）は取引先や経営者などになりすまして送金を誘導し，金銭をだまし取る手口。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-02','exam-sg','情報セキュリティ機関・組織','standard','single_choice','【2019年度 令和元年秋期 午前 問2】参加組織及びそのグループ企業で検知されたサイバー攻撃などの情報を，IPAが情報ハブになって集約し，参加組織間で共有する取組はどれか。','[{"id":"a","text":"CRYPTREC"},{"id":"b","text":"CSIRT"},{"id":"c","text":"J-CSIP"},{"id":"d","text":"JISEC"}]','"c"','J-CSIPはサイバー情報共有イニシアティブ。IPAが情報を集約・共有するハブとなる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-03','exam-sg','ISMS・リスク受容','standard','single_choice','【2019年度 令和元年秋期 午前 問3】JIS Q 27001:2014において，リスクを受容するプロセスに求められるものはどれか。','[{"id":"a","text":"受容するリスクについては，リスク所有者が承認すること"},{"id":"b","text":"受容するリスクを監視やレビューの対象外とすること"},{"id":"c","text":"リスクの受容は，リスク分析前に行うこと"},{"id":"d","text":"リスクを受容するかどうかは，リスク対応後に決定すること"}]','"a"','リスク受容にはリスク所有者の承認が必要。受容したリスクも監視・レビューを続ける。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-04','exam-sg','人的セキュリティ・内部不正','standard','single_choice','【2019年度 令和元年秋期 午前 問4】退職する従業員による不正を防ぐための対策として，IPA「組織における内部不正防止ガイドライン（第4版）」に照らして適切なものはどれか。','[{"id":"a","text":"秘密保持誓約書では秘密保持の対象を明示せず，重要情報を客観的に特定できないようにする。"},{"id":"b","text":"職業選択の自由を行使しないことを明記し，範囲を設定しない包括的な競業避止義務契約を入社時に締結する。"},{"id":"c","text":"退職後も利用者IDや権限を有効にしておき，持出しなどの不正行為を調査できるようにする。"},{"id":"d","text":"退職予定者に対する重要情報へのアクセスや媒体の持出しの監視を強化する。"}]','"d"','退職直前の情報持出しリスクに備え，アクセス権と媒体持出しを重点的に監視する。退職時にはID・権限も停止する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-05','exam-sg','ISMS・是正処置','standard','single_choice','【2019年度 令和元年秋期 午前 問5】JIS Q 27000:2019において，不適合が発生した場合にその原因を除去し，再発を防止するためのものはどれか。','[{"id":"a","text":"継続的改善"},{"id":"b","text":"修正"},{"id":"c","text":"是正処置"},{"id":"d","text":"リスクアセスメント"}]','"c"','是正処置は不適合の根本原因を除去して再発を防止する。修正は発生した不適合そのものを直すこと。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-06','exam-sg','IoT・Telnet','standard','single_choice','【2019年度 令和元年秋期 午前 問6】ネットワークカメラなどのIoT機器ではTCP 23番ポートへの攻撃が多い理由はどれか。','[{"id":"a","text":"TCP 23番ポートは機器の操作に使うTelnetで使用され，初期パスワードによる不正ログインが成功しやすいから"},{"id":"b","text":"TCP 23番ポートを使うと，マルウェアを添付した電子メールを機器へ送信できるから"},{"id":"c","text":"TCP 23番ポートは機器へのメール送信用であり，初期パスワードによる不正ログインが成功しやすいから"},{"id":"d","text":"TCP 23番ポートはメール送信用であり，マルウェア付きメールを機器へ送信できるから"}]','"a"','TCP 23番ポートはTelnetで使われる。初期パスワードのまま公開されたIoT機器は不正ログインの標的になりやすい。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-07','exam-sg','メール認証・SPF','standard','single_choice','【2019年度 令和元年秋期 午前 問7】SPF（Sender Policy Framework）の仕組みはどれか。','[{"id":"a","text":"受信サーバがメールに付与されたディジタル署名で送信元ドメインの詐称がないことを確認する。"},{"id":"b","text":"受信サーバが送信元ドメイン情報と送信サーバのIPアドレスから，送信元ドメインの詐称がないことを確認する。"},{"id":"c","text":"送信サーバが宛先ドメインや送信者を問わず全てのメールをアーカイブする。"},{"id":"d","text":"送信者の上司の承認が得られるまでメール送信を保留する。"}]','"b"','SPFはDNSに登録された送信許可サーバのIPアドレスと実際の送信元を照合する。電子署名で検証する説明とは異なる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-08','exam-sg','VDI・マルウェア対策','standard','single_choice','【2019年度 令和元年秋期 午前 問8】社内PCから直接インターネット上のWebサイトを参照する方式を，DMZ上のVDIサーバにログインし，仮想デスクトップ上のブラウザで参照する方式に変更する。期待できるセキュリティ上の効果はどれか。','[{"id":"a","text":"インターネット上のWebサイトから内部ネットワークのPCへのマルウェアのダウンロードを防ぐ。"},{"id":"b","text":"Webサイト利用時にMITB攻撃による送信データの改ざんを防ぐ。"},{"id":"c","text":"内部PCと仮想デスクトップのOSがボットに感染しなくなり，C&Cサーバに制御されることを防ぐ。"},{"id":"d","text":"内部PCにマルウェアが侵入しても，他のPCへの感染を防ぐ。"}]','"a"','VDIにインターネット閲覧環境を分離することで，Web経由のファイルやマルウェアが利用者PCへ直接届くリスクを低減できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-09','exam-sg','クラウド・JIS Q 27017','standard','single_choice','【2019年度 令和元年秋期 午前 問9】JIS Q 27002:2014には記載されていないが，JIS Q 27017:2016に記載されている管理策はどれか。','[{"id":"a","text":"クラウドサービス固有の情報セキュリティ管理策"},{"id":"b","text":"事業継続マネジメントシステムにおける管理策"},{"id":"c","text":"情報セキュリティガバナンスにおける管理策"},{"id":"d","text":"制御システム固有のサイバーセキュリティ管理策"}]','"a"','JIS Q 27017はクラウドサービスの利用者・提供者向けに，クラウド固有の情報セキュリティ管理策を示す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-10','exam-sg','シャドーIT','standard','single_choice','【2019年度 令和元年秋期 午前 問10】シャドーITに該当するものはどれか。','[{"id":"a","text":"IT製品やITを活用して地球環境への負荷を低減する取組"},{"id":"b","text":"IT部門の許可を得ずに，従業員又は部門が業務に利用しているデバイスやクラウドサービス"},{"id":"c","text":"攻撃対象者のディスプレイやキータイプを物陰から盗み見て情報を盗み出す行為"},{"id":"d","text":"侵入対象の弱点を探すために組織や従業員の情報を収集すること"}]','"b"','シャドーITは組織のIT部門が把握・管理していないデバイスやクラウドサービスを業務利用すること。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-11','exam-sg','ステガノグラフィ','standard','single_choice','【2019年度 令和元年秋期 午前 問11】ステガノグラフィはどれか。','[{"id":"a","text":"画像などのデータの中に，秘密にしたい情報を他者に気付かれることなく埋め込む。"},{"id":"b","text":"検索エンジンの巡回ロボットに閲覧者とは異なる内容を応答し，検索順位を上げる。"},{"id":"c","text":"問題を引き起こしそうなテストデータを製品に送信し，挙動から脆弱性を検出する。"},{"id":"d","text":"ゆがんだ文字を画像表示して利用者に入力させ，人間であることを確認する。"}]','"a"','ステガノグラフィは情報の存在そのものを気付かれないように隠す技術。暗号化は内容を読めなくする技術。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-12','exam-sg','ハッシュ関数・SHA-256','standard','single_choice','【2019年度 令和元年秋期 午前 問12】SHA-256でファイルAとファイルBのハッシュ値を算出すると，同じ値 n（16進数64桁）になった。この結果から考えられることとして適切なものはどれか。\nハッシュ値 n：86620f2f 152524d7 dbed4bcb b8119bb6 d493f734 0b4e7661 88565353 9e6d2074','[{"id":"a","text":"各内容を変更せず再計算すると，AとBのハッシュ値は異なる。"},{"id":"b","text":"ハッシュ値nのデータ量は64バイトである。"},{"id":"c","text":"AとBを連結したファイルCのハッシュ値は16進数128桁になる。"},{"id":"d","text":"ファイルAの内容とファイルBの内容は同じである。"}]','"d"','SHA-256の出力は256ビット＝16進数64桁。ハッシュ値が一致しても数学的に内容同一を絶対保証するわけではないが，設問の選択肢では同一内容が適切。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-13','exam-sg','MITB・トランザクション署名','standard','single_choice','【2019年度 令和元年秋期 午前 問13】インターネットバンキングでのMITB攻撃による不正送金対策として用いられるトランザクション署名の説明はどれか。','[{"id":"a","text":"携帯端末での送金時，金融機関から登録メールアドレスに送金用ワンタイムパスワードを送信する。"},{"id":"b","text":"認定認証局が署名したディジタル証明書を利用者認証に用い，ログインパスワード漏えい時の不正ログインを防ぐ。"},{"id":"c","text":"送金処理を行うPCとは別のデバイスに振込先口座番号などの取引情報を入力し，表示された値を送信する。"},{"id":"d","text":"ログイン時に別デバイスで一定時間だけ有効なログイン用ワンタイムパスワードを算出し送信する。"}]','"c"','トランザクション署名は取引内容そのものを別デバイスで確認・署名するため，ログイン後に振込先等を書き換えるMITB攻撃への対策になる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-14','exam-sg','WAF・フォールスポジティブ','standard','single_choice','【2019年度 令和元年秋期 午前 問14】WAFにおけるフォールスポジティブに該当するものはどれか。','[{"id":"a","text":"「<」を検出したら遮断する設定で，数式を含む正当なHTTPリクエストを攻撃と誤検知して遮断する。"},{"id":"b","text":"WAFが検査しない独自フィールドを悪用した攻撃リクエストを遮断しない。"},{"id":"c","text":"許可しない文字列を含む不正なHTTPリクエストを攻撃と検知して遮断する。"},{"id":"d","text":"悪意のある通信を正常に見せかけ，分割したHTTPリクエストを遮断しない。"}]','"a"','フォールスポジティブ（偽陽性）は正常な通信を攻撃と誤判定すること。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja'),
('sg-official-2019f-am-15','exam-sg','ボットネット・C&C','standard','single_choice','【2019年度 令和元年秋期 午前 問15】ボットネットにおいてC&Cサーバが担う役割はどれか。','[{"id":"a","text":"遠隔操作が可能なマルウェアに，情報収集及び攻撃活動を指示する。"},{"id":"b","text":"攻撃の踏み台となった複数のサーバからの通信を制御して遮断する。"},{"id":"c","text":"電子商取引事業者などに偽のディジタル証明書の発行を命令する。"},{"id":"d","text":"不正なWebコンテンツのテキスト，画像及びレイアウト情報を一元管理する。"}]','"a"','C&C（Command and Control）サーバは感染端末へ指令を送り，情報収集やDDoSなどの攻撃活動を制御する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000dict-att/2019r01a_sg_am_qs.pdf','ja');
